struct PracticeView: View {
    @State private var isPaused = false

    var body: some View {
        ZStack {
            Button("Pause") { isPaused.toggle() }
            if isPaused {
                Color.black.opacity(0.4).ignoresSafeArea()
                Button("Weiter") { isPaused.toggle() }
                    .buttonStyle(.glassProminent)
            }
        }
    }
}

