import SwiftUI

struct ShopButton: View {
    @Binding var coins: Int
    @Binding var potions: Int

    var body: some View {
        Button("Trank kaufen") {
            guard coins >= 25 else { return }
            coins -= 25
            potions += 1
        }
        .disabled(coins < 25)
    }
}

